INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(32391566, 'Extra Veiler', '额外遮蔽者', 'エクストラ・ヴェーラー', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 600, 200, '对方把怪兽特殊召唤时，可以从手卡把这张卡特殊召唤。这个效果特殊召唤的回合，对方的卡的效果发生的对自己的效果伤害由对方代受。'),
(57995165, 'Extra-Foolish Burial', '愚蠢的重葬', 'おろかな重葬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能把魔法·陷阱卡盖放。 ①：把基本分支付一半才能发动。从额外卡组把1只怪兽送去墓地。'),
(38383368, 'Extraceratops', '临时保险三角龙装', 'エキストラケアトップス', 'Effect Monster', 'Warrior', 'EARTH', 1, 100, 100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在墓地存在，额外怪兽区域的怪兽被和主要怪兽区域的怪兽的战斗破坏送去墓地时才能发动。这张卡在那只破坏的额外怪兽区域的怪兽的持有者场上守备表示特殊召唤。 ②：这张卡的①的效果特殊召唤的这张卡被破坏送去墓地的场合发动。自己从卡组抽1张。'),
(23617756, 'Exxod Fires of Rage', '愤怒的业火 艾克佐德之炎', '怒りの業火 エクゾード・フレイム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「艾格佐德」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有10星以上的「艾克佐迪亚」怪兽存在的场合才能发动。对方场上的卡全部破坏。 ②：可以把这个回合没有送去墓地的这张卡从墓地除外，从以下效果选择1个发动。 ●从自己的卡组·墓地把1只「被封印」怪兽加入手卡。 ●自己的墓地·除外状态的最多5只「被封印」怪兽回到卡组。'),
(55737443, 'Exxod, Master of The Guard', '守护神 艾克佐德', '守護神エクゾード', 'Effect Monster', 'Rock', 'EARTH', 8, NULL, 4000, '这张卡不能通常召唤。把自己场上存在的1只名字带有「斯芬克斯」的怪兽解放的场合才能特殊召唤。只要这张卡在场上表侧表示存在，地属性怪兽反转召唤成功时，给与对方基本分1000分伤害。'),
(23446369, 'Eye of Illusion', '幻惑之眼', '幻惑の眼', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有幻想魔族或魔法师族的怪兽存在的场合，可以从以下效果选择1个发动。 ●这个回合中，自己的幻想魔族·魔法师族怪兽不会被战斗破坏。 ●对方回合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。 ●对方怪兽的攻击宣言时，以攻击怪兽以外的对方场上1只表侧表示怪兽为对象才能发动。攻击对象转移为那只怪兽进行伤害计算。'),
(57047293, 'Eye of the Void', '苍焰的炼狱', '蒼焔の煉獄', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡把1只「狱火机」怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的效果直到回合结束时无效化。'),
(64511793, 'Eyearmor', '复印者', 'コピックス', 'Normal Monster', 'Warrior', 'EARTH', 2, 600, 500, '变身成为各种敌人的模样，从而欺骗对方进行战斗的战士。'),
(39271553, 'F.A. Auto Navigator', '方程式运动员导航仪', 'F.A.カーナビゲーター', 'Tuner Monster', 'Machine', 'WIND', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，以自己场上1只持有比原本等级高的等级的「方程式运动员」怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽的等级下降和那个原本等级的相差数值。这个效果特殊召唤的这张卡的等级变成和那个相差数值相同。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「方程式运动员」场地魔法卡加入手卡。'),
(39838559, 'F.A. Circuit Grand Prix', '方程式运动员赛道大奖赛', 'F.A.サーキットGP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，场上的「方程式运动员」怪兽的等级只在战斗阶段内上升2星。 ②：1回合1次，自己的「方程式运动员」怪兽战斗破坏对方怪兽时才能发动。自己从卡组抽1张。 ③：场上的表侧表示的这张卡被效果破坏的场合才能发动。从卡组把「方程式运动员赛道大奖赛」以外的1张「方程式运动员」卡加入手卡。'),
(1061200, 'F.A. City Grand Prix', '方程式运动员城市大奖赛', 'F.A.シティGP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，场上的「方程式运动员」怪兽的等级只在主要阶段以及战斗阶段内上升2星。 ②：自己场上的「方程式运动员」怪兽不会成为对方的效果的对象。 ③：场上的表侧表示的这张卡被效果破坏的场合才能发动。从卡组把「方程式运动员市街大奖赛」以外的1张「方程式运动员」卡加入手卡。'),
(6764709, 'F.A. Dark Dragster', '方程式运动员 黑暗御主', 'F.A.ダークネスマスター', 'Effect Monster', 'Machine', 'DARK', 7, NULL, 2000, '这张卡不能通常召唤。场上有7星以上的「方程式运动员」怪兽存在，自己的怪兽区域没有「方程式运动员 暗冥赛道名将」存在的场合可以特殊召唤。 ①：这张卡的攻击力上升这张卡的等级×300。 ②：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ③：1回合1次，以场上1张卡为对象才能发动。这张卡的等级下降3星，那张卡破坏。'),
(33158448, 'F.A. Dawn Dragster', '方程式运动员 光明御主', 'F.A.ライトニングマスター', 'Synchro Monster', 'Machine', 'LIGHT', 7, NULL, 2000, '调整＋调整以外的怪兽1只以上 ①：这张卡的攻击力上升这张卡的等级×300。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ④：1回合1次，对方把魔法·陷阱卡的效果发动时才能发动。这张卡的等级下降2星，那个发动无效并破坏。'),
(5641251, 'F.A. Dead Heat', '方程式运动员白热化', 'F.A.デッド・ヒート', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方怪兽的直接攻击宣言时才能发动。从卡组把1只「方程式运动员」怪兽特殊召唤。 ②：自己的「方程式运动员」怪兽和对方怪兽进行战斗的伤害计算前才能发动1次。双方各掷1次骰子。自己的出现数目比对方大的场合，那只进行战斗的自己怪兽的等级直到回合结束时上升4星。自己的出现数目比对方小的场合，那只自己怪兽破坏。出现的数目相同的场合，重掷骰子。'),
(66322203, 'F.A. Downforce', '方程式运动员下压力', 'F.A.ダウンフォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「方程式运动员」怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升2星。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只「方程式运动员」怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升2星。这个效果在这张卡送去墓地的回合不能发动。'),
(93449450, 'F.A. Hang On Mach', '方程式运动员 侧挂马赫', 'F.A.ハングオンマッハ', 'Effect Monster', 'Machine', 'WIND', 4, NULL, 1800, '①：这张卡的攻击力上升这张卡的等级×300，不受原本的等级或者阶级比这张卡的等级低的对方怪兽发动的效果影响。 ②：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ③：这张卡的等级是7星以上的场合，被送去对方墓地的卡不去墓地而除外。'),
(75676192, 'F.A. Motorhome Transport', '方程式运动员运载房车', 'F.A.ホームトランスポーター', 'Synchro Monster', 'Machine', 'LIGHT', 9, NULL, 3000, '调整＋调整以外的怪兽1只以上 ①：这张卡的攻击力上升这张卡的等级×300。 ②：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ③：这张卡得到这张卡的等级的以下效果。 ●11星以上：这张卡不会被战斗·效果破坏。 ●13星以上：1回合1次，以自己墓地1只「方程式运动员」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(2144946, 'F.A. Off-Road Grand Prix', '方程式运动员越野大奖赛', 'F.A.オフロードGP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在场地区域存在，场上的「方程式运动员」怪兽的等级只在主要阶段内上升2星。 ②：自己的「方程式运动员」怪兽被战斗破坏时才能发动。对方手卡随机选1张丢弃。 ③：场上的表侧表示的这张卡被效果破坏的场合才能发动。从卡组把「方程式运动员越野大奖赛」以外的1张「方程式运动员」卡加入手卡。'),
(32036866, 'F.A. Overheat', '方程式运动员过热化', 'F.A.オーバー・ヒート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只有对方场上才有怪兽存在的场合才能发动。从手卡把1只「方程式运动员」怪兽特殊召唤。这个效果特殊召唤的怪兽的等级直到回合结束时上升3星。 ②：自己的场地区域没有卡存在的场合，把墓地的这张卡除外才能发动。从自己的手卡·墓地选1张「方程式运动员」场地魔法卡发动。'),
(38532954, 'F.A. Pit Stop', '方程式运动员修理站', 'F.A.ピットストップ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「方程式运动员」怪兽为对象才能发动。那只怪兽的等级下降2星，自己从卡组抽出自己墓地的「方程式运动员进站」的数量＋1张。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「方程式运动员」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(37414347, 'F.A. Shining Star GT', '方程式运动员 辉耀明星・超跑级', 'F.A.シャイニングスターGT', 'Link Monster', 'Machine', 'LIGHT', NULL, NULL, NULL, '机械族怪兽2只 这个卡名的④的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡所连接区的「方程式运动员」怪兽的等级合计×300。 ②：这张卡的战斗发生的双方的战斗伤害变成0。 ③：「方程式运动员」魔法·陷阱卡的效果发动的场合发动。给这张卡放置1个运动员指示物。 ④：对方把怪兽的效果发动时，把这张卡1个运动员指示物取除才能发动。那个发动无效并破坏。'),
(67045745, 'F.A. Sonic Meister', '方程式运动员 音速大师', 'F.A.ソニックマイスター', 'Effect Monster', 'Machine', 'WIND', 4, NULL, 1000, '①：这张卡的攻击力上升这张卡的等级×300，不会被和原本的等级或者阶级比这张卡的等级低的对方怪兽的战斗破坏。 ②：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ③：这张卡的等级是7星以上的场合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(38459905, 'F.A. Test Run', '方程式运动员试跑', 'F.A.シェイクダウン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「方程式运动员」怪兽为对象才能发动。那只怪兽的表示形式变更。那之后，选场上1张卡破坏。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1张表侧表示的卡为对象才能发动。那张卡破坏，从卡组把1只「方程式运动员」怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(75059201, 'F.A. Turbo Charger', '方程式运动员 涡轮增压机战车', 'F.A.ターボチャージャー', 'Effect Monster', 'Machine', 'WIND', 6, NULL, 1500, '①：这张卡的攻击力上升这张卡的等级×300，原本的等级或者阶级比这张卡的等级低的对方怪兽只能以这张卡作为攻击对象，只能以这张卡作为效果的对象。 ②：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ③：这张卡的等级是7星以上，自己的「方程式运动员」怪兽进行战斗的场合，直到伤害步骤结束时对方不能把怪兽的效果发动。'),
(49655592, 'F.A. Whip Crosser', '方程式运动员 激摆越野骑手', 'F.A.ウィップクロッサー', 'Effect Monster', 'Machine', 'WIND', 4, NULL, 1000, '①：这张卡的攻击力上升这张卡的等级×300，对方若不支付300基本分，则不能把原本的等级或者阶级比这张卡的等级低的怪兽的效果发动。 ②：「方程式运动员」魔法·陷阱卡的效果发动的场合才能发动（伤害步骤也能发动）。这张卡的等级上升1星。 ③：这张卡的等级是7星以上的场合，对方不能把要把手卡丢弃发动的效果以及要把手卡送去墓地发动的效果发动。'),
(69553552, 'F.A. Winners', '方程式运动员胜者', 'F.A.ウィナーズ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「方程式运动员」怪兽存在的场合，这张卡不会被对方的效果破坏。 ②：持有比原本等级高5星以上的等级的自己的「方程式运动员」怪兽用和对方怪兽的战斗给与对方战斗伤害时才能发动。选自己的手卡·场上·墓地1张卡除外。「方程式运动员胜利团队」的效果除外的自己的「方程式运动员」场地魔法3种类齐集时，自己决斗胜利。'),
(28270534, 'FA.I.ghting Spirit', '鼓劲-艾-', 'キ－Ai－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「@火灵天星」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己场上的攻击力2300以上的「@火灵天星」怪兽被效果破坏的场合，可以作为代替把墓地的这张卡除外。 ③：这张卡被除外的场合才能发动。这个回合，自己的攻击力2300以上的「@火灵天星」怪兽不会被战斗破坏。'),
(9061682, 'Fabled Andwraith', '魔轰神安德雷斯', '魔轟神アンドレイス', 'Synchro Monster', 'Fiend', 'LIGHT', 6, 2400, 1900, '「魔轰神」调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。对方可以选1张手卡丢弃让这个效果无效。没丢弃的场合，自己抽2张。抽卡的场合，再选自己1张手卡丢弃。 ②：怪兽从对方手卡送去墓地的场合，以那之内的1只为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(12235475, 'Fabled Ashenveil', '魔轰神 亚申维尔', '魔轟神アシェンヴェイル', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1600, 1200, '①：这张卡进行战斗的那次伤害计算时1次，把1张手卡送去墓地才能发动。这张卡的攻击力只在那次伤害计算时上升600。'),
(53199020, 'Fabled Dianaira', '魔轰神迪亚涅拉', '魔轟神ディアネイラ', 'Effect Monster', 'Fiend', 'LIGHT', 8, 2800, 100, '这张卡可以把1只「魔轰神」怪兽解放表侧攻击表示上级召唤。 ①：只要这张卡在怪兽区域存在，对方把通常魔法卡发动的场合，1回合只有1次让那个效果变成「对方选1张手卡丢弃」。'),
(86840720, 'Fabled Dyf', '魔轰神 迪夫', '魔轟神ディフ', 'Effect Monster', 'Fiend', 'LIGHT', 3, 1400, 1700, '名字带有「魔轰神」的怪兽从手卡送去自己墓地时，把自己场上存在的这张卡解放，选择那1只怪兽才能发动。选择怪兽在自己场上特殊召唤。'),
(60434101, 'Fabled Gallabas', '魔轰神 加尔巴斯', '魔轟神ガルバス', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1500, 800, '把1张手卡丢弃去墓地发动。持有这张卡的攻击力以下的守备力的对方场上表侧表示存在的1只怪兽破坏。'),
(94292987, 'Fabled Gammajin', '魔轰神加缪基', '魔轟神ガミュジン', 'Synchro Tuner Monster', 'Fiend', 'LIGHT', 4, 2000, NULL, '「魔轰神」调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从手卡·卡组把1只「魔轰神」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能把自己场上的其他的「魔轰神」同调怪兽作为效果的对象。 ③：这张卡被送去墓地的场合才能发动。自己抽出自己场上的「魔轰神」同调怪兽的数量。那之后，选自己1张手卡丢弃。'),
(24040093, 'Fabled Grimro', '魔轰神格里蒙罗', '魔轟神グリムロ', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1700, 1000, '①：自己场上有「魔轰神」怪兽存在的场合，把这张卡从手卡送去墓地才能发动。从卡组把「魔轰神 葛琳萝」以外的1只「魔轰神」怪兽加入手卡。'),
(19439119, 'Fabled Krus', '魔轰神克露丝', '魔轟神クルス', 'Effect Monster', 'Fiend', 'LIGHT', 2, 1000, 800, '①：这张卡从手卡丢弃去墓地的场合，以自己墓地1只其他的4星以下的「魔轰神」怪兽为对象发动。那只怪兽特殊召唤。'),
(97439806, 'Fabled Kushano', '魔轰神苛黠诺', '魔轟神クシャノ', 'Tuner Monster', 'Fiend', 'LIGHT', 3, 1100, 800, '①：这张卡在墓地存在的场合，从手卡把「魔轰神 库沙诺」以外的1只「魔轰神」怪兽丢弃去墓地才能发动。这张卡加入手卡。'),
(39477584, 'Fabled Leviathan', '魔轰神勒维亚坦', '魔轟神レヴュアタン', 'Synchro Monster', 'Fiend', 'LIGHT', 10, 3000, 2000, '「魔轰神」调整＋调整以外的怪兽1只以上 ①：场上的这张卡被破坏送去墓地时，以自己墓地最多3只「魔轰神」怪兽为对象才能发动。那些怪兽加入手卡。'),
(21281085, 'Fabled Levilazebul', '魔轰神勒邪则步', '魔轟神レヴェルゼブル', 'Synchro Monster', 'Fiend', 'LIGHT', 10, 3050, 1950, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己·对方的主要阶段才能发动1次。自己场上的「魔轰神」怪兽任意数量解放，得到那个数量的对方场上的表侧表示怪兽的控制权。这个效果得到控制权的怪兽的效果无效化。 ②：这张卡在墓地存在的场合，以自己墓地1张其他的「魔轰神」卡为对象才能发动。这张卡回到额外卡组，作为对象的卡加入手卡。'),
(97651498, 'Fabled Lurrie', '魔轰神鲁力', '魔轟神ルリー', 'Effect Monster', 'Fiend', 'LIGHT', 1, 200, 400, '①：这张卡从手卡丢弃去墓地的场合发动。这张卡特殊召唤。'),
(57630503, 'Fabled Marcosia', '魔轰神马可西亚', '魔轟神マルコシア', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1700, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。从手卡选包含「魔轰神」怪兽在内的最多2只「魔轰神 马可西亚」以外的怪兽丢弃，这张卡特殊召唤。这个效果特殊召唤的这张卡的攻击力上升这个效果丢弃的怪兽数量×200。 ②：这张卡从手卡丢弃去墓地的场合发动。从卡组把1张「魔轰神」魔法·陷阱卡加入手卡。'),
(8316661, 'Fabled Miztoji', '魔轰神 米兹托西', '魔轟神ミーズトージ', 'Tuner Monster', 'Fiend', 'LIGHT', 2, 400, 200, '把这张卡从手卡送去墓地，选择自己场上表侧表示存在的1只名字带有「魔轰神」的怪兽发动。选择怪兽只要在场上表侧表示存在当作调整使用。'),
(49633574, 'Fabled Oltro', '魔轰神 欧特罗', '魔轟神オルトロ', 'Tuner Monster', 'Fiend', 'LIGHT', 2, 800, 500, '把1张手卡送去墓地发动。从手卡把1只3星的名字带有「魔轰神」的怪兽特殊召唤。这个效果1回合只能使用1次。'),
(47395382, 'Fabled Ragin', '魔轰神雷吉翁', '魔轟神レイジオン', 'Synchro Monster', 'Fiend', 'LIGHT', 5, 2300, 1800, '「魔轰神」调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤时才能发动。自己直到手卡变成2张为止抽卡。'),
(47217354, 'Fabled Raven', '魔轰神雷文', '魔轟神レイヴン', 'Tuner Monster', 'Fiend', 'LIGHT', 2, 1300, 1000, '①：1回合1次，自己主要阶段才能发动。选自己手卡任意数量丢弃，直到回合结束时，这张卡的等级上升丢弃数量的数值，攻击力上升丢弃数量×400。'),
(57775790, 'Fabled Realm''s Revival', '魔轰神界的复活', '魔轟神界の復活', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把「魔轰神界的复活」以外的1张「魔轰神」魔法·陷阱卡在自己场上盖放。 ②：只要这张卡在魔法与陷阱区域存在，在自己的「魔轰神」同调怪兽的同调召唤成功时对方不能把卡的效果发动。 ③：1回合1次，可以从手卡丢弃1张「魔轰神」卡，从以下效果选择1个发动。 ●自己抽1张。 ●自己的墓地·除外状态的1只「魔轰神」怪兽特殊召唤。'),
(72328962, 'Fabled Soulkius', '魔轰神索尔基乌斯', '魔轟神ソルキウス', 'Effect Monster', 'Fiend', 'LIGHT', 6, 2200, 2100, '①：这张卡在墓地存在的场合，从手卡把「魔轰神 索尔基乌斯」以外的2张卡送去墓地才能发动。这张卡特殊召唤。'),
(46833854, 'Fabled Topi', '魔轰神托比', '魔轟神トピー', 'Effect Monster', 'Fiend', 'LIGHT', 1, 500, 200, '①：自己手卡比对方少2张以上的场合，把手卡1只「魔轰神」怪兽给对方观看，把这张卡解放，以对方场上2张魔法·陷阱卡为对象才能发动。那些对方的卡破坏。'),
(55766177, 'Fabled Treason', '弑逆之魔轰神', '弑逆の魔轟神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「魔轰神」怪兽和场上1张表侧表示卡为对象才能发动。选自己1张手卡丢弃，作为对象的墓地的怪兽特殊召唤，作为对象的场上的卡破坏。'),
(73040500, 'Fabled Urustos', '魔轰神 乌尔史特斯', '魔轟神ウルストス', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1500, 200, '自己手卡是2张以下的场合，自己场上表侧表示存在的名字带有「魔轰神」的怪兽的攻击力上升400。'),
(54048462, 'Fabled Valkyrus', '魔轰神瓦尔基鲁斯', '魔轟神ヴァルキュルス', 'Synchro Monster', 'Fiend', 'LIGHT', 8, 2900, 1700, '「魔轰神」调整＋调整以外的怪兽1只以上 ①：1回合1次，从手卡丢弃1只恶魔族怪兽才能发动。自己抽1张。'),
(29062925, 'Face Card Fusion', '绘札融合', '絵札融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把战士族·光属性的融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。自己场上有「王后骑士」「卫兵骑士」「国王骑士」的其中任意种存在的场合，自己卡组的怪兽也能有最多1只作为融合素材。'),
(39276790, 'Face-Off', '真剑胜负', '真剣勝負', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：伤害步骤有怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(7030340, 'Factory of 100 Machines', '百机夜工', '百機夜工', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己墓地存在的名字带有「变形斗士」的怪兽全部从游戏中除外。自己场上表侧表示存在的1只机械族怪兽的攻击力直到这个回合的结束阶段时这个效果每除外1只怪兽上升200。'),
(48742406, 'Fairy Archer', '妖精弓手', 'フェアリー・アーチャー', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1400, 600, '自己的主要阶段时，可以给与对方基本分自己场上表侧表示存在的光属性怪兽每1只400分伤害。这个效果发动的回合这张卡不能攻击。「妖精弓手」的效果1回合只能使用1次。'),
(44451698, 'Fairy Archer Ingunar', '妖精弓士 因古纳尔', '妖精弓士イングナル', 'Effect Monster', 'Plant', 'EARTH', 6, 2400, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡用植物族怪兽的效果特殊召唤成功的场合，以自己墓地1只6星以上的植物族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。 ②：这张卡在特殊召唤的回合不能攻击。'),
(21598948, 'Fairy Box', '怪兽箱', 'モンスターBOX', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己准备阶段支付500基本分。或者不支付基本分让这张卡破坏。 ①：对方怪兽的攻击宣言时发动。进行1次投掷硬币，对里表作猜测。猜中的场合，那只攻击怪兽的攻击力只要这张卡在魔法与陷阱区域存在直到战斗阶段结束时变成0。'),
(51960178, 'Fairy Cheer Girl', '妖精啦啦队少女', 'フェアリー・チア・ガール', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 1900, 1500, '天使族4星怪兽×2 把这张卡1个超量素材取除才能发动。从卡组抽1张卡。「妖精啦啦队少女」的效果1回合只能使用1次。'),
(20315854, 'Fairy Dragon', '精灵龙', 'フェアリー・ドラゴン', 'Normal Monster', 'Dragon', 'WIND', 4, 1100, 1200, '在妖精中意外地强，非常漂亮的龙妖精。'),
(22419772, 'Fairy Guardian', '妖精守护者', 'ピクシーガーディアン', 'Effect Monster', 'Fairy', 'WIND', 3, 1000, 1000, '表侧表示的这张卡做祭品。这个回合因为对方造成的送去墓地的自己的1张魔法卡回到卡组最下面。'),
(28290705, 'Fairy King Albverdich', '妖精王 阿尔维德', '妖精王 アルヴェルド', 'XYZ Monster', 'Plant', 'EARTH', 4, 2300, 1400, '地属性4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。地属性以外的场上的全部怪兽的攻击力·守备力下降500。'),
(45425051, 'Fairy King Truesdale', '妖精王 奥布朗', '妖精王オベロン', 'Effect Monster', 'Plant', 'WATER', 6, 2200, 1500, '①：只要这张卡在怪兽区域守备表示存在，自己场上的植物族怪兽的攻击力·守备力上升500。'),
(19684740, 'Fairy Knight Ingunar', '妖精骑士 因古纳尔', '妖精騎士イングナル', 'XYZ Monster', 'Plant', 'EARTH', 6, 2200, 3000, '6星怪兽×3 ①：1回合1次，把这张卡2个超量素材取除才能发动。这张卡以外的场上的卡全部回到持有者手卡。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。'),
(97687912, 'Fairy Meteor Crush', '流星直击', 'メテオ・ストライク', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(81563416, 'Fairy of the Fountain', '泉之妖精', '泉の妖精', 'Normal Monster', 'Aqua', 'WATER', 4, 1600, 1100, '守护泉水的精灵。对任何污浊泉水者杀无赦。'),
(20188127, 'Fairy of the Spring', '泉之精灵', '泉の精霊', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己的墓地里选择1张装备魔法卡加入手卡。这张装备魔法卡本回合不能发动。'),
(86937530, 'Fairy Tail - Luna', '妖精传姬－辉夜', '妖精伝姫－カグヤ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1000, '①：这张卡召唤时才能发动。从卡组把1只攻击力1850的魔法师族怪兽加入手卡。 ②：自己·对方回合1次，以对方场上1只表侧表示怪兽为对象才能发动。对方可以把1张那只怪兽的同名卡从自身的卡组·额外卡组送去墓地让这个效果无效。没送去墓地的场合，这张卡和作为对象的怪兽回到手卡。'),
(19144622, 'Fairy Tail - Matchlille', NULL, NULL, 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1000, NULL),
(52022648, 'Fairy Tail - Rella', '妖精传姬－辛德瑞拉', '妖精伝姫－シンデレラ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1000, '①：只要这张卡在怪兽区域存在，双方不能把场上的其他怪兽作为魔法卡的效果的对象。 ②：1回合1次，从手卡丢弃1张魔法卡才能发动。把这张卡可以装备的1张装备魔法卡从自己的手卡·卡组·墓地装备。那张装备魔法卡在结束阶段回到手卡。'),
(65953423, 'Fairy Tail - Rochka', '妖精传姬-罗奇卡', '妖精伝姫－ラチカ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。对方回复500基本分。那之后，对方从把这个效果发动的玩家的卡组上面把3张卡确认，从那之中选1张。自己把对方选的卡加入手卡。剩余回到卡组。 ②：这张卡进行战斗的伤害计算前才能发动。这张卡送去墓地。'),
(42921475, 'Fairy Tail - Sleeper', '妖精传姬－塔利娅', '妖精伝姫－ターリア', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡反转的场合才能发动。从手卡把1只怪兽特殊召唤。 ②：对方把通常魔法·通常陷阱卡发动时，把自己场上1只其他怪兽解放才能发动。那个效果变成「对方场上1只表侧表示怪兽变成里侧守备表示」。'),
(55623480, 'Fairy Tail - Snow', '妖精传姬－白雪', '妖精伝姫－シラユキ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1000, '①：这张卡召唤·特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：自己·对方回合，这张卡在墓地存在的场合，从自己的手卡·场上·墓地把这张卡以外的7张卡除外才能发动。这张卡特殊召唤。'),
(27632520, 'Fairy Tail - Wickat', NULL, NULL, 'XYZ Monster', 'Spellcaster', 'DARK', 4, 1850, 1000, NULL),
(56725612, 'Fairy Tail Ball', NULL, NULL, 'Spell Card', 'Field', NULL, NULL, NULL, NULL, NULL),
(19326613, 'Fairy Tail Long Long Ago', NULL, NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, NULL),
(91957038, 'Fairy Tail Tales', '妖精的传姬', '妖精の伝姫', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把同名怪兽不在自己场上存在的手卡1只攻击力1850的魔法师族怪兽给对方观看才能发动。进行那只怪兽的通常召唤。 ②：自己场上有原本攻击力是1850的魔法师族怪兽存在，自己因战斗·效果受到伤害的场合，1回合只有1次让那次伤害变成0。'),
(43236494, 'Fairy Tale Prologue: Journey''s Dawn', '童话序章 启程之晓光', 'Fairy Tale 序章 旅立ちの暁光', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，双方受到的战斗伤害变成一半。 ②：自己场上有兽族·光属性怪兽或者7·8星的龙族同调怪兽存在的场合才能发动。自己抽1张。 ③：自己准备阶段，把场地区域的这张卡送去墓地才能发动。从自己的手卡·卡组把「童话故事 序章 启程的曙光」以外的1张场地魔法卡在自己的场地区域表侧表示放置。'),
(73507661, 'Fairy Wind', '妖精之风', '妖精の風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的魔法·陷阱卡全部破坏，双方受到破坏的卡数量×300的数值的伤害。'),
(68401546, 'Fairy''s Gift', '妖精的赠礼', '妖精の贈りもの', 'Normal Monster', 'Spellcaster', 'LIGHT', 4, 1400, 1000, '据说能使任何人幸福的魔法一边飞一边散发着。'),
(17653779, 'Fairy''s Hand Mirror', '天使的手镜', '天使の手鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把以场上1只怪兽为对象发动的对方的魔法，转移给其他正确的对象。'),
(53416326, 'Fairyant the Circular Sorcerer', '圆唤师 菲尔莉', '円喚師フェアリ', 'Tuner Monster', 'Insect', 'WIND', 3, 800, 1500, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己或者对方的墓地有昆虫族·植物族怪兽的其中任意种存在的场合，这张卡可以从手卡特殊召唤。 ②：把自己场上的这张卡作为昆虫族·植物族同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。'),
(37160778, 'Fairywitch', '天使・魔女', 'エンジェル・魔女', 'Normal Monster', 'Spellcaster', 'DARK', 3, 800, 1000, '背负着成为天使的命运，但却成为了向往中的魔女。'),
(86038337, 'Faisan, Hunting Scout of the Deep Forest', '深林狩哨 雉鸡', NULL, 'Fusion Monster', 'Warrior', 'EARTH', 5, 2300, 2300, '战士族·地属性怪兽×2 这张卡在主要阶段期间不受对方发动的效果影响。 战斗阶段（诱发即时效果）：可以把融合召唤的这张卡解放；从自己墓地把「深林狩哨 雉鸡」以外的2只战士族·地属性怪兽特殊召唤，再让自己场上的战士族·地属性怪兽直到回合结束时不会被战斗破坏。「深林狩哨 雉鸡」的这个效果1回合只能使用1次。'),
(75582395, 'Faith Bird', '圣鸟', 'セイント・バード', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1500, 1100, '尾巴非常长的鸟，全身散发出神圣的光芒。'),
(41234315, 'Fake Explosion', '伪爆炸五星', 'フェイク・エクスプロージョン・ペンタ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。怪兽不会被那次战斗破坏，伤害计算后从自己的手卡或者墓地把1只「召唤反应机·大式」特殊召唤。'),
(22628574, 'Fake Feather', '伪羽', 'フェイク・フェザー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「黑羽」的怪兽送去墓地，选择对方墓地存在的1张通常陷阱卡发动。这张卡的效果变成和选择的通常陷阱卡的效果相同。'),
(78387742, 'Fake Hero', '冒牌英雄', 'フェイク・ヒーロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡特殊召唤1只名字带有「元素英雄」的怪兽。那只怪兽不能攻击，这个回合的结束阶段时回到持有者手卡。'),
(3027001, 'Fake Trap', '伪陷阱', '偽物のわな', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上的陷阱卡破坏的魔法·陷阱·效果怪兽的效果对方发动时才能发动，把这张卡作为代替破坏，其他的自己的陷阱卡不破坏。盖放的卡破坏的场合，那些卡全部翻开确认。'),
(86170989, 'Falchion Beta', '大刀贝塔', 'ファルシオンβ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 800, '这张卡战斗破坏对方怪兽的场合，从下面效果选择1个发动。 ●从自己卡组选择1只攻击力1200以下的机械族·光属性怪兽送去墓地。 ●选择自己墓地存在的1只攻击力1200以下的机械族·光属性怪兽特殊召唤。'),
(93023136, 'Fallen Angel in Darkness', '堕入黑暗的天使', '闇に堕ちた天使', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「堕天使」卡使用。这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上（表侧表示）把1只天使族怪兽送去墓地才能发动。自己的手卡·卡组·除外状态的1只「堕天使」怪兽无视召唤条件特殊召唤。'),
(49674183, 'Fallen Angel of Roses', '魔天使 蔷薇之巫师', '魔天使ローズ・ソーサラー', 'Effect Monster', 'Plant', 'EARTH', 7, 2400, 1300, '这张卡可以让「魔天使 蔷薇之巫师」以外的自己场上表侧表示存在的1只植物族怪兽回到手卡，从手卡特殊召唤。这个方法特殊召唤的这张卡从场上离开的场合从游戏中除外。'),
(43143567, 'Fallen Angel of the Golden Land', '黄金乡堕天像', '黄金郷のアンヘルカイド', 'Fusion Monster', 'Zombie', 'DARK', 10, 1800, 2500, '「黄金卿 黄金国巫妖」＋不死族怪兽 「黄金乡的堕落天使」1回合1次用融合召唤以及以下方法才能特殊召唤。 ●自己的场上或墓地有「黄金卿 黄金国巫妖」存在的状态，把自己场上1只不死族·光属性怪兽解放的场合可以从额外卡组特殊召唤。 这个卡名的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合才能发动。从自己的卡组·额外卡组·墓地把1只「黄金国巫妖」怪兽特殊召唤。'),
(68468459, 'Fallen of Albaz', '阿尔白斯之落胤', 'アルバスの落胤', 'Effect Monster', 'Dragon', 'DARK', 4, 1800, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，丢弃1张手卡才能发动。包含这张卡的自己·对方场上的怪兽作为融合素材，把1只融合怪兽融合召唤。那个时候，不能把自己场上的其他怪兽作为融合素材。'),
(82090807, 'Fallen of Argyros', '阿尔银洛斯之落胤', 'アルギロスの落胤', 'Effect Monster', 'Thunder', 'DARK', 2, 700, 700, '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。 ①：场上有2星·2阶·连接2的怪兽的其中任意种存在的场合，这张卡可以从手卡往自己或者对方场上特殊召唤。 ②：双方不能把有这张卡位于所连接区的连接怪兽的效果发动。 ③：对方回合，以场上1只超量怪兽为对象才能发动。那只怪兽最多2个超量素材取除。'),
(87498729, 'Fallen of the Tistina', '提斯蒂娜的遗落之子', 'ティスティナの落とし仔', 'Effect Monster', 'Aqua', 'WATER', 1, 200, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地才能发动。从卡组把1张「神域 巴普-提斯蒂娜」在自己的场地区域表侧表示放置。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的「提斯蒂娜」魔法·陷阱卡被对方的效果破坏的场合，把这张卡除外才能发动。从自己的手卡·卡组·墓地把1只光属性「提斯蒂娜」怪兽特殊召唤。'),
(73819701, 'Fallen of the White Dragon', '白之落胤', '白き竜の落胤', 'Effect Monster', 'Dragon', 'DARK', 4, 1800, NULL, '这个卡名在规则上当作「阿不思的落胤」使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从额外卡组把有「阿不思的落胤」的卡名记述的1只怪兽送去墓地才能发动。这张卡特殊召唤。这个回合，自己不是8星的融合·同调怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从自己的手卡·卡组·墓地把1只「艾克莉西娅」怪兽特殊召唤。'),
(13301895, 'Fallen Paradise', '失乐园', '失楽園', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，自己的怪兽区域的「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」「混沌幻魔 阿米泰尔」不会成为对方的效果的对象，不会被对方的效果破坏。 ②：自己的怪兽区域有「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」「混沌幻魔 阿米泰尔」的其中任意种存在的场合才能发动。自己从卡组抽2张。'),
(90312154, 'Fallen Sanctuary', '失落的圣域', '失われた聖域', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，从卡组选1张「天空的圣域」或者有那个卡名记述的魔法·陷阱卡在自己场上盖放。 ②：这张卡的卡名只要在场上·墓地存在当作「天空的圣域」使用。 ③：从自己墓地把1只天使族怪兽除外，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(59011257, 'Fallin'' Cheatah', '坠入情网的猎豹', 'フォーリンチーター', 'Effect Monster', 'Beast', 'FIRE', 3, 1100, 2200, '①：这张卡只要在怪兽区域存在，不能解放，也不能作为融合·同调·超量·连接召唤的素材。 ②：这张卡在怪兽区域存在的状态，对方场上有怪兽特殊召唤的场合，以那之内的1只为对象发动。这张卡的控制权移给作为对象的怪兽的控制者。这只怪兽表侧表示存在期间，作为对象的怪兽不能解放，也不能作为融合·同调·超量·连接召唤的素材。'),
(26099457, 'Falling Current', '下降潮流', '下降潮流', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽，宣言从1到3的任意等级才能发动。选择的怪兽的等级变成宣言的等级。'),
(32919136, 'Falling Down', '堕落', '堕落', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '可以给对方场上的怪兽装备。 ①：得到装备怪兽的控制权。 ②：对方准备阶段发动。自己受到800伤害。 ③：自己场上没有「恶魔」卡存在的场合这张卡破坏。'),
(89731911, 'Familiar Knight', '亲善骑士', 'ファミリア・ナイト', 'Effect Monster', 'Warrior', 'DARK', 3, 1200, 1400, '①：这张卡被战斗破坏送去墓地的场合发动。双方玩家可以从手卡把1只4星怪兽特殊召唤。'),
(31887905, 'Familiar-Possessed - Aussa', '凭依装着－奥丝', '憑依装着－アウス', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1850, 1500, '①：这张卡可以把自己场上的表侧表示的1只「地灵使 奥丝」和1只地属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(21390858, 'Familiar-Possessed - Dharc', '凭依装着－达尔克', '憑依装着－ダルク', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1850, 1500, '可以把自己场上1只「暗灵使 达克」和1只暗属性怪兽送去墓地，从手卡·卡组特殊召唤。这个方法特殊召唤成功时，可以从卡组把1只3星或者4星的魔法师族·光属性怪兽加入手卡。此外，这个方法特殊召唤的这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(68881649, 'Familiar-Possessed - Eria', '凭依装着－艾里雅', '憑依装着－エリア', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1850, 1500, '①：这张卡可以把自己场上的表侧表示的1只「水灵使 艾莉娅」和1只水属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(4376658, 'Familiar-Possessed - Hiita', '凭依装着－希塔', '憑依装着－ヒータ', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1850, 1500, '①：这张卡可以把自己场上的表侧表示的1只「火灵使 希塔」和1只炎属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(40542825, 'Familiar-Possessed - Lyna', '凭依装着－莱娜', '憑依装着－ライナ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1850, 1500, '①：这张卡可以把自己场上的表侧表示的1只「光灵使 莱娜」和1只光属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤时才能发动。从卡组把「凭依装着-莱娜」以外的1只守备力1500的魔法师族怪兽加入手卡。 ③：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(31764353, 'Familiar-Possessed - Wynn', '凭依装着－薇茵', '憑依装着－ウィン', 'Effect Monster', 'Spellcaster', 'WIND', 4, 1850, 1500, '①：这张卡可以把自己场上的表侧表示的1只「风灵使 薇茵」和1只风属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(45538320, 'Familiars of the Spiritual Arts', NULL, NULL, 'Effect Monster', 'Reptile', 'WATER', 4, 1500, 200, NULL),
(26162470, 'Fandora, the Flying Fighting Furtress', '飞龙战艇－帆朵拉', '飛竜戦艇－ファンドラ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「空牙团」卡使用。这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的「空牙团」怪兽的攻击力上升自己场上的「空牙团」怪兽种类×300。 ②：自己主要阶段才能发动。从卡组把1只「空牙团」怪兽加入手卡。那之后，选自己1张手卡丢弃。 ③：自己场上的表侧表示的「空牙团」怪兽被对方的效果破坏的场合才能发动。从卡组把1只「空牙团」怪兽特殊召唤。'),
(64400161, 'Fandora, the Flying Furtress', '飞龙艇－帆朵拉', '飛竜艇－ファンドラ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己抽卡阶段的抽卡前才能发动。作为这个回合进行通常抽卡的代替，从卡组把1只「空牙团」怪兽加入手卡。 ②：自己场上有「空牙团」怪兽5种类以上存在的场合，把场地区域的这张卡送去墓地才能发动。对方场上的卡全部破坏。这个效果的发动后，直到回合结束时对方受到的全部伤害变成0。'),
(79176962, 'Fantastic Striborg', '旋风机 风神电子人', '旋風機ストリボーグ', 'Effect Monster', 'Machine', 'WIND', 5, 2200, 2200, '这张卡表侧表示上级召唤的场合解放的怪兽不送去墓地回到持有者手卡。 ①：1回合1次，丢弃1张手卡才能发动。和这张卡相同纵列的对方场上的卡全部回到持有者手卡。'),
(78661338, 'Fantastical Dragon Phantazmay', '幻创龙幻紫魅', '幻創龍ファンタズメイ', 'Effect Monster', 'Dragon', 'DARK', 7, 2400, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把连接怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。那之后，自己抽出对方场上的连接怪兽的数量＋1张。那之后，选对方场上的连接怪兽数量的自己手卡回到卡组。 ②：自己场上的怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，丢弃1张手卡才能发动。那个发动无效并破坏。'),
(32785578, 'Farewelcome Labrynth', '感谢光临拉比丽斯', 'フェアーウェルカム・ラビュリンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有恶魔族怪兽存在的场合，自己或者对方的怪兽的攻击宣言时，以场上1张卡为对象才能发动。那次攻击无效，作为对象的卡破坏。那之后，可以从手卡·卡组选「拉比林斯迷宫」卡以外的1张通常陷阱卡在自己场上盖放。'),
(36553319, 'Farfa, Malebranche of the Burning Abyss', '彼岸恶鬼 法法雷鲁', '彼岸の悪鬼 ファーファレル', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1900, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽直到结束阶段除外。'),
(27001740, 'Farm Delivery', '来自农园的配送', '農園からの配送', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有通常怪兽存在的场合，以除外的最多3只自己的通常怪兽为对象才能发动。那些怪兽回到卡组。'),
(54100561, 'FaSolfachord Fancia', '发音服和弦・潘西娅', 'ファドレミコード・ファンシア', 'Pendulum Effect Monster', 'Fairy', 'FIRE', 4, 1600, 400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己主要阶段才能发动。从卡组把「发之七音服·凡西娅」以外的1只「七音服」灵摆怪兽表侧加入额外卡组。 ②：自己的灵摆区域有奇数的灵摆刻度存在，自己的「七音服」灵摆怪兽被战斗破坏的场合，可以作为代替把这张卡破坏。'),
(77910045, 'Fatal Abacus', '死之演算盘', '死の演算盤', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次怪兽从场上送去墓地，每1张卡使那张卡的主人受到500分的伤害。'),
(39568067, 'Fateful Adventure', '命运的旅途', '運命の旅路', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把有「勇者衍生物」的衍生物名记述的1只怪兽加入手卡。那之后，选自己1张手卡送去墓地。 ②：怪兽召唤·特殊召唤的场合才能发动。从卡组选有「勇者衍生物」的衍生物名记述的1张装备魔法卡加入手卡或给自己场上1只「勇者衍生物」装备。 ③：1回合只有1次，有装备卡装备的自己怪兽不会被战斗破坏。'),
(786906, 'Fateful Hour', '逢魔之刻', '逢魔ノ刻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己或者对方的墓地1只不能通常召唤的怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(68396778, 'Faustian Bargain', '给恶魔的贡物', '悪魔への貢物', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上1只特殊召唤的怪兽送去墓地，从手卡把1只4星以下的通常怪兽特殊召唤。'),
(75047173, 'Favorite Contact', '至爱接触', 'フェイバリット・コンタクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上·墓地·除外状态让融合怪兽决定的融合素材怪兽用喜欢的顺序回到卡组下面，把以「英雄」怪兽为融合素材的那1只融合怪兽从额外卡组无视召唤条件特殊召唤。这个效果让「元素英雄 新宇侠」回到卡组的场合，双方不能让这个效果特殊召唤的怪兽回到额外卡组。'),
(11881272, 'Favorite Hero', '至爱英雄', 'フェイバリット・ヒーロー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '5星以上的「英雄」怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：自己的场地区域有卡存在的场合，装备怪兽攻击力上升原本守备力数值，对方不能把装备怪兽作为效果的对象。 ②：自己·对方的战斗阶段开始时才能发动。从自己的手卡·卡组把1张场地魔法卡发动。 ③：装备怪兽的攻击破坏对方怪兽时，把这张卡送去墓地才能发动。那只攻击怪兽只再1次可以继续攻击。'),
(34193084, 'Fear from the Dark', '来自黑暗的恐怖', '闇よりの恐怖', 'Effect Monster', 'Zombie', 'DARK', 4, 1700, 1500, '当这张卡被对方的效果从手卡或卡组送去墓地时，这张卡特殊召唤上场。'),
(55416843, 'Feast of the Wild LV5', '蛮族的狂宴LV5', '蛮族の狂宴LV５', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·墓地选最多2只战士族·5星怪兽特殊召唤。这个效果特殊召唤的怪兽效果无效化，这个回合不能攻击。'),
(19394153, 'Feather Shot', '羽翼散射', 'フェザー・ショット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只「元素英雄 羽翼侠」发动。这个回合，选择的卡可以进行和自己场上的怪兽同样数目的攻击。那个场合，不能直接攻击对方玩家，其它的自己怪兽不能攻击。'),
(71060915, 'Feather Wind', '羽翼之风', 'フェザー・ウィンド', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有「元素英雄 羽翼侠」表侧表示存在的场合才能发动。魔法·陷阱卡的发动无效，并把那张卡破坏。'),
(32271987, 'Featherizer', '费德莱扎', 'フェデライザー', 'Effect Monster', 'Spellcaster', 'WIND', 2, 700, 1100, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只二重怪兽送去墓地，从自己卡组抽1张卡。'),
(50785356, 'Feedback Warrior', '啸叫战士', 'ハウリング・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 3, 800, 700, '这张卡召唤·特殊召唤成功时，选择自己场上表侧表示存在的1只怪兽才能发动。选择的怪兽的等级变成3星。'),
(92597893, 'Feedran, the Winds of Mischief', '恶作剧风之幼龙妖精', 'いたずら風のフィードラン', 'Effect Monster', 'Dragon', 'WIND', 3, 1700, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：对方回合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽的表示形式变更。那之后，这张卡回到持有者手卡。'),
(3954901, 'Felgrand Dragon', '闪耀巨龙', 'フェルグラントドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2800, 2800, '这张卡不是从墓地中不能特殊召唤，若没已从场上送去墓地则也不能作从墓地的特殊召唤。 ①：这张卡从墓地的特殊召唤成功的场合，以自己墓地1只怪兽为对象发动。这张卡的攻击力上升作为对象的怪兽的等级×200。'),
(73176465, 'Felis, Lightsworn Archer', '光道弓箭手・菲莉丝', 'ライトロード・アーチャー フェリス', 'Tuner Monster', 'Beast-Warrior', 'LIGHT', 4, 1100, 2000, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：这张卡被怪兽的效果从卡组送去墓地的场合发动。这张卡特殊召唤。 ②：把这张卡解放，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏。那之后，从自己卡组上面把3张卡送去墓地。'),
(97396380, 'Fencing Fire Ferret', '火舞太刀', '火舞太刀', 'Effect Monster', 'Beast', 'FIRE', 4, 1700, 600, '①：这张卡被破坏送去墓地的场合，以对方场上1只表侧表示怪兽为对象发动。那只对方的表侧表示怪兽破坏，给与对方500伤害。'),
(50866755, 'Fenghuang', '凤凰', '鳳凰', 'Spirit Monster', 'Winged Beast', 'FIRE', 6, 2100, 1800, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，对方场上盖放的魔法·陷阱卡全部破坏。'),
(35311929, 'Fengli the Soldrapom', '阳龙果 凤梨', '陽竜果フォンリー', 'Tuner Monster', 'Plant', 'FIRE', 1, 800, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡被怪兽的效果从卡组送去墓地的场合才能发动。这张卡特殊召唤。自己场上有其他的植物族怪兽存在的场合，可以再选场上1只怪兽那个攻击力·守备力变成一半。 ②：1回合1次，场上的这张卡被战斗·效果破坏的场合，可以作为代替从卡组把1只植物族怪兽送去墓地。'),
(37406863, 'Fengsheng Mirror', '封神镜', '封神鏡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '看对方手卡。对方手卡有灵魂怪兽存在的场合，选择1只灵魂怪兽丢弃去墓地。'),
(218704, 'Fenrir', '芬里尔', 'フェンリル', 'Effect Monster', 'Beast', 'WATER', 4, 1400, 1200, '这张卡不能进行通常召唤。从自己墓地里除外2只水属性怪兽进行特殊召唤。这张卡战斗破坏对方怪兽时，略过对方的下一个抽卡阶段。'),
(91697229, 'Fenrir the Nordic Wolf', '极星邪狼 芬里尔', '極星邪狼フェンリル', 'Effect Monster', 'Beast', 'DARK', 10, 4000, 4000, '这张卡不能通常召唤。自己主要阶段2，场上有「极神」怪兽存在的场合可以从手卡往对方场上守备表示特殊召唤。 ①：场上没有「极神」怪兽存在的场合这张卡破坏。 ②：自己战斗阶段开始时发动。自己场上的守备表示怪兽全部变成表侧攻击表示。 ③：这张卡的战斗发生的战斗伤害由双方玩家承受。'),
(41392891, 'Feral Imp', '戈兰林', 'グレムリン', 'Normal Monster', 'Fiend', 'DARK', 4, 1300, 1400, '喜欢恶作剧的小恶魔，从黑暗中袭来。警惕！'),
(98642179, 'Ferocious Flame Swordsman', '刚炎之骑士', '剛炎の剣士', 'Link Monster', 'Warrior', 'FIRE', NULL, 1300, NULL, '卡名不同的怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，场上的战士族怪兽的攻击力上升500。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合，以连接怪兽以外的自己墓地1只战士族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(31044787, 'Ferret Flames', '太刀鼬的大爆发', 'イタチの大暴発', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上的表侧表示怪兽的攻击力合计数值比自己基本分高的场合才能发动。直到对方场上的表侧表示怪兽的攻击力合计数值变成自己基本分以下为止，对方必须选自身场上的攻击力是0以外的表侧表示怪兽回到持有者卡组。'),
(6696168, 'Festiballoon', '庆典气球', 'フェスティバルーン', 'Effect Monster', 'Illusion', 'LIGHT', 8, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ②：只要这张卡在怪兽区域存在，每次自己或对方的怪兽攻击宣言，这张卡的攻击力上升1000。 ③：自己主要阶段才能发动。这张卡的攻击力下降5000，场上的其他卡全部破坏。'),
(78706415, 'Fiber Jar', '纤维壶', 'ファイバーポッド', 'Flip Effect Monster', 'Plant', 'EARTH', 3, 500, 500, '反转：双方把自己场上的卡，手卡，墓地的卡和卡组合在一起洗切。之后各自从卡组抽5张卡。'),
(70088809, 'Fidraulis Harmonia', NULL, NULL, 'Tuner Monster', 'Dragon', 'DARK', 7, 2500, 2000, NULL),
(7153114, 'Field Barrier', '场地防护罩', 'フィールドバリア', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方不能把场地魔法卡破坏，也不能作场地魔法卡的发动。「场地防护罩」在自己场上只能有1张表侧表示存在。'),
(89529919, 'Field-Commander Rahz', '战士 拉兹', '戦士ラーズ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1200, '这张卡召唤·特殊召唤成功时，从自己卡组选择「战士 拉兹」以外的1只4星以下的战士族怪兽在卡组最上面放置。'),
(81172176, 'Fiend Comedian', '魔鬼喜剧演员', 'デビル・コメディアン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：进行1次投掷硬币，对硬币的里表作猜测。猜中的场合，对方墓地的卡全部除外。猜错的场合，把对方墓地的卡数量的卡从自己卡组上面送去墓地。'),
(60743819, 'Fiend Griefing', '魔鬼的叹息', '悪魔の嘆き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方墓地1只怪兽为对象才能发动。那只怪兽回到对方卡组。那之后，可以从自己卡组把1只恶魔族怪兽送去墓地。'),
(77456781, 'Fiend Kraken', '恶魔乌贼', 'デビル・クラーケン', 'Normal Monster', 'Aqua', 'WATER', 4, 1200, 1400, '潜在海里的巨大章鱼。从海中突然出现并攻击。'),
(56838842, 'Fiend Piece Golem', NULL, NULL, 'Effect Monster', 'Fiend', 'DARK', 5, 2100, NULL, NULL),
(68870276, 'Fiend Reflection #1', '绝镜吸收鸟', 'アブソリューター', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '可以将对方吸入镜中世界。'),
(2863439, 'Fiend Reflection #2', '幻象鸟', 'ミラージュ', 'Normal Monster', 'Winged Beast', 'LIGHT', 4, 1100, 1400, '能够从手里的镜子中召唤出同伴的鸟怪。'),
(63947968, 'Fiend Reflection of the Millennium', '千年绝镜吸收鸟', 'ミレニアム・アブソリューター', 'Effect Monster', 'Illusion', 'WIND', 4, 1300, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续魔法卡使用的状态，对方的效果发动的场合才能发动。这张卡特殊召唤。那之后，可以让自己基本分回复场上1只怪兽的攻击力一半的数值。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(26566878, 'Fiend Scorpion', '恶魔蝎', 'デビルスコーピオン', 'Normal Monster', 'Insect', 'EARTH', 2, 900, 200, '寄宿着恶魔灵魂的巨大蝎子。平时蕴存着力量，但是潜在的能力很高。'),
(66235877, 'Fiend Skull Dragon', '死亡恶魔龙', 'デス・デーモン・ドラゴン', 'Fusion Monster', 'Dragon', 'WIND', 5, 2000, 1200, '「巨龙」＋「下位恶魔」 这张卡的融合召唤不用上记的卡不能进行。 ①：只要这张卡在怪兽区域存在，反转怪兽的效果无效化。 ②：只要这张卡在怪兽区域存在，这张卡为对象的陷阱卡的效果无效化并破坏。'),
(22855882, 'Fiend Sword', '被诅咒的魔剑', '呪われし魔剣', 'Normal Monster', 'Warrior', 'DARK', 4, 1400, 800, '据说战胜施加在身上的诅咒的人就可以以此获得力量。'),
(52800428, 'Fiend''s Hand', '死者之腕', '死者の腕', 'Normal Monster', 'Zombie', 'DARK', 2, 600, 600, '从混沌沼泽中伸出手腕，将生者拖入其中。'),
(58607704, 'Fiend''s Hand Mirror', '恶魔的手镜', '悪魔の手鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '使对方发动的以1张魔法·陷阱卡为对象的魔法移向另外1个正确的对象。'),
(31890399, 'Fiend''s Mirror', '恶魔镜', 'デビルズ・ミラー', 'Ritual Monster', 'Fiend', 'DARK', 6, 2100, 1800, '「恶魔镜的仪式」降临。'),
(24874630, 'Fiend''s Sanctuary', '恶魔的圣域', 'デビルズ・サンクチュアリ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：在自己场上把1只「金属恶魔衍生物」（恶魔族·暗·1星·攻/守0）特殊召唤。这衍生物不能攻击，这衍生物的战斗发生的对控制者的战斗伤害由对方代受。这衍生物的控制者在每次自己准备阶段支付1000基本分。或者不支付基本分让这衍生物破坏。'),
(50078509, 'Fiendish Chain', '噩魔锁链', 'デモンズ・チェーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以场上1只效果怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，作为对象的表侧表示怪兽不能攻击，效果无效化。作为对象的怪兽破坏时这张卡破坏。'),
(82556058, 'Fiendish Engine Omega', '恶性马达・欧米伽', 'デモニック・モーター・Ω', 'Effect Monster', 'Machine', 'DARK', 8, 2800, 2000, '①：1回合1次，自己主要阶段才能发动。这张卡的攻击力直到回合结束时上升1000。 ②：这张卡的①的效果发动的场合，结束阶段发动。这张卡破坏。 ③：自己结束阶段发动。在自己场上把1只「马达衍生物」（机械族·地·1星·攻/守200）攻击表示特殊召唤。'),
(24662957, 'Fiendish Golem', '噩魔魔像', 'デモンズ・ゴーレム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只攻击力2000以上的怪兽为对象才能发动。那只怪兽直到下个回合的结束阶段除外。自己场上有着「红莲魔龙」或者有那个卡名记述的同调怪兽存在的状态把这张卡发动的场合，可以再从自己的卡组·墓地把1张「魔族之链」在自己场上盖放。'),
(1759808, 'Fiendish Portrait', '幻魔的肖像', '幻魔の肖像', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽为对象才能发动。把1只那只怪兽的同名怪兽从自己的卡组·额外卡组特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段回到持有者卡组。这张卡的发动后，直到回合结束时自己不能从卡组·额外卡组把怪兽特殊召唤。'),
(81035362, 'Fiendish Rhino Warrior', '魔犀战士', '魔サイの戦士', 'Effect Monster', 'Fiend', 'EARTH', 3, 1400, 900, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，「魔犀族战士」以外的自己场上的恶魔族怪兽不会被战斗·效果破坏。 ②：这张卡被送去墓地的场合才能发动。从卡组把「魔犀族战士」以外的1只恶魔族怪兽送去墓地。'),
(60764609, 'Fiendsmith Engraver', '刻魔印契之魔镌客', '魔を刻むデモンスミス', 'Effect Monster', 'Fiend', 'LIGHT', 6, 1800, 2400, '这个卡名的①②③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「刻魔」魔法·陷阱卡加入手卡。 ②：以自己场上1张「刻魔」装备卡和场上1只怪兽为对象才能发动。那些卡送去墓地。 ③：这张卡在墓地存在的场合，从自己墓地让1只其他的恶魔族·光属性怪兽回到卡组·额外卡组才能发动。这张卡特殊召唤。'),
(99989863, 'Fiendsmith in Paradise', '契印魔镌・乐园颂', '刻まれし魔の楽園', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只7星以上的恶魔族·光属性怪兽为对象才能发动。那只怪兽以外的场上的卡全部送去墓地。 ②：这张卡在墓地存在的状态，对方把怪兽特殊召唤的场合，把这张卡除外才能发动。从卡组·额外卡组把1只「刻魔」怪兽送去墓地。'),
(26434972, 'Fiendsmith Kyrie', '契印魔镌・怜歌颂', '刻まれし魔の憐歌', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这个回合中，自己的恶魔族·光属性怪兽不会被战斗破坏，自己受到的战斗伤害变成一半。 ②：把墓地的这张卡除外才能发动。自己场上的怪兽作为融合素材，把1只「刻魔」融合怪兽融合召唤。那个时候，「刻魔」怪兽装备的自己的魔法与陷阱区域的当作装备魔法卡使用的融合素材怪兽也能作为融合素材使用。'),
(32991300, 'Fiendsmith''s Agnumday', '契印魔镌・神羔棺', '刻まれし魔の神聖棺', 'Link Monster', 'Fiend', 'LIGHT', NULL, 1800, NULL, '包含恶魔族·光属性怪兽的怪兽2只以上 ①：自己·对方回合1次，以连接怪兽以外的自己墓地1只恶魔族·光属性怪兽为对象才能发动。那只怪兽特殊召唤，自己场上的这张卡当作持有以下效果的装备魔法卡使用给那只怪兽装备。 ●装备怪兽的攻击力上升给自身装备的连接怪兽的连接标记合计×600。 ●装备怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(82135803, 'Fiendsmith''s Desirae', '怒魔镌刻・迪厄斯伊雷', '刻まれし魔ディエスイレ', 'Fusion Monster', 'Fiend', 'LIGHT', 9, 2800, 2400, '「刻印群魔的刻魔锻冶师」＋恶魔族·光属性怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合可以发动。选最多有给这张卡装备的连接怪兽的连接标记合计数量的场上的表侧表示卡，那些效果直到回合结束时无效。 ②：这张卡被送去墓地的场合，从自己墓地让1只其他的恶魔族·光属性怪兽回到卡组·额外卡组，以场上1张卡为对象才能发动。那张卡送去墓地。'),
(46640168, 'Fiendsmith''s Lacrima', '泪魔镌刻・拉克莉末莎', '刻まれし魔ラクリモーサ', 'Fusion Monster', 'Fiend', 'LIGHT', 6, 2400, 2400, '恶魔族·光属性怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，以自己的墓地·除外状态的1只恶魔族·光属性怪兽为对象才能发动。那只怪兽加入手卡或特殊召唤。 ②：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力下降600。 ③：这张卡被送去墓地的场合，从自己墓地让1只其他的恶魔族·光属性怪兽回到卡组·额外卡组才能发动。给与对方1200伤害。'),
(2463794, 'Fiendsmith''s Requiem', '契印魔镌・镇魂棺', '刻まれし魔の鎮魂棺', 'Link Monster', 'Fiend', 'LIGHT', NULL, 600, NULL, '恶魔族·光属性怪兽1只 自己对「刻魔的镇魂棺」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：自己·对方的主要阶段，把这张卡解放才能发动。从手卡·卡组把1只「刻魔」怪兽特殊召唤。 ②：以连接怪兽以外的自己场上1只恶魔族·光属性怪兽为对象才能发动。从自己的场上·墓地把这张卡当作攻击力上升600的装备魔法卡使用给那只自己怪兽装备。'),
(11464648, 'Fiendsmith''s Rextremende', '威魔镌刻・雷克斯托雷米德', '刻まれし魔レクストレメンデ', 'Fusion Monster', 'Fiend', 'LIGHT', 9, 3000, 3600, '「刻魔」融合怪兽＋融合·连接怪兽 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，丢弃1张手卡才能发动。从卡组·额外卡组把1只恶魔族·光属性怪兽送去墓地。 ②：这张卡只要有「刻魔」装备魔法卡装备，不受「刻魔」卡以外的卡的效果影响。 ③：这张卡被送去墓地的场合，以自己的墓地·除外状态的1张其他的「刻魔」卡为对象才能发动。那张卡加入手卡。'),
(35552985, 'Fiendsmith''s Sanct', '契印魔镌・赞圣颂', '刻まれし魔の讃聖', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示怪兽不存在的场合或者只有恶魔族·光属性怪兽的场合才能发动。在自己场上把1只「刻魔衍生物」（恶魔族·光·1星·攻/守0）特殊召唤。这个回合，自己不用恶魔族怪兽不能攻击宣言。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的「刻魔」怪兽被对方的效果破坏的场合才能发动。这张卡在自己场上盖放。'),
(49867899, 'Fiendsmith''s Sequence', '契印魔镌・叙圣棺', '刻まれし魔の大聖棺', 'Link Monster', 'Fiend', 'LIGHT', NULL, 1200, NULL, '包含恶魔族·光属性怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己墓地的怪兽作为融合素材回到卡组，把1只恶魔族融合怪兽融合召唤。 ②：以连接怪兽以外的自己场上1只恶魔族·光属性怪兽为对象才能发动。从自己的场上·墓地把这张卡当作持有以下效果的装备魔法卡使用给那只自己怪兽装备。 ●对方不能把装备怪兽作为效果的对象。'),
(98567237, 'Fiendsmith''s Tract', '契印魔镌・咏圣颂', '刻まれし魔の詠聖', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只恶魔族·光属性怪兽加入手卡。那之后，选自己1张手卡丢弃。 ②：把墓地的这张卡除外才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「刻魔」融合怪兽融合召唤。'),
(27012717, 'Fierce Tiger Monghu', '猛虎', '猛虎モンフー', 'Effect Monster', 'Beast', 'EARTH', 4, 1700, 1000, '①：只要这张卡在怪兽区域存在，这张卡以外的场上的怪兽的攻击力下降500。 ②：1回合1次，自己主要阶段才能发动。持有比这张卡低的攻击力的场上的怪兽全部破坏。'),
(68054593, 'Fiery Fervor', '燃烧的斗志', '燃える闘志', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上表侧表示存在的1只怪兽装备。攻击力比原本攻击力高的怪兽在对方场上存在的场合，装备怪兽的攻击力在伤害步骤内变成原本攻击力的2倍。'),
(55428811, 'Fifth Hope', '第五幕之希望', 'ホープ・オブ・フィフス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的5张名字带有「元素英雄」的卡，加入卡组洗切。之后，从自己卡组抽2张卡。这张卡的发动时自己场上以及手卡没有其他卡存在的场合抽3张卡。'),
(85862791, 'Fighting Dirty', '同盗相窃', '泥仕合', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己以及对方场上的卡同时被战斗·效果破坏的场合才能发动。双方玩家各自从卡组抽2张。'),
(36319131, 'Fighting Flame Dragon', '斗气炎斩龙', '闘気炎斬龍', 'Fusion Monster', 'Dragon', 'FIRE', 5, 1700, 1600, '龙族怪兽＋战士族·炎属性怪兽 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方回合，以自己场上1只战士族融合怪兽为对象才能发动。从自己的场上·墓地把这张卡当作装备魔法卡使用给那只自己怪兽装备。 ②：只要这张卡给「炎之剑士」或者有那个卡名记述的怪兽装备中，装备怪兽的攻击力上升700，同1次的战斗阶段中可以作2次攻击。'),
(35697544, 'Fighting Flame Sword', '斗气炎斩剑', '闘気炎斬剣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●除「斗气炎斩剑」外的1张有「炎之剑士」的卡名记述的卡从卡组加入手卡。 ●自己的战士族·炎属性怪兽进行战斗的攻击宣言时，以场上1张卡为对象才能发动。那张卡破坏。 ●以自己场上的「炎之剑士」或者有那个卡名记述的怪兽为对象的效果由对方发动时才能发动。那个效果无效。'),
(1047075, 'Fighting Flame Swordsman', '斗炎之剑士', '闘炎の剣士', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把有「炎之剑士」的卡名记述的1张魔法·陷阱卡加入手卡。 ②：这张卡被送去墓地的场合才能发动。除「斗炎之剑士」外的1只「炎之剑士」或者有那个卡名记述的怪兽从卡组·额外卡组送去墓地。'),
(6178850, 'Fighting Spirit', '斗魂', 'ファイティング・スピリッツ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力对方场上存在的怪兽每有1只上升300。装备怪兽被战斗破坏的场合，可以作为代替把这张卡破坏。'),
(78293584, 'Filia Diabell', '狂怒・迪亚贝尔', 'フィリアス・ディアベル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只8星以上的「迪亚贝尔」怪兽加入手卡。只有对方场上才有怪兽存在的场合，也能不加入手卡特殊召唤。 ②：这张卡被除外的场合才能发动。自己场上的全部「迪亚贝尔」怪兽的攻击力上升500。'),
(70538272, 'Filia Regis', '妖龙之禁姬', '妖竜の禁姫', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, 2500, '龙族融合怪兽＋7星以上的龙族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以对方的场上·墓地1张卡为对象才能发动。那张卡除外。把场上的卡除外的场合，再让自己场上1只龙族怪兽回到手卡。 ②：这张卡在墓地存在的场合，对方战斗阶段开始时才能发动。自己场上1只龙族怪兽回到手卡·额外卡组，这张卡特殊召唤。'),
(36205132, 'Filo, Messenger Fur Hire', '空牙团的传令 菲萝', '空牙団の伝令 フィロ', 'Effect Monster', 'Winged Beast', 'WIND', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的传令 菲勒」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「空牙团」怪兽特殊召唤的场合，以自己墓地1只「空牙团」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合回到持有者卡组最下面。'),
(52503575, 'Final Attack Orders', '最终突击命令', '最終突撃命令', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，场上的表侧表示怪兽变成攻击表示，不能把表示形式变更。'),
(54261514, 'Final Bringer of the End Times', '超兽的咆哮', '超獸の咆哮', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只怪兽和对方场上1张卡为对象才能发动。那些卡破坏。'),
(95308449, 'Final Countdown', '终焉的倒计时', '終焉のカウントダウン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付2000基本分才能发动。以发动的回合为第1回合来计算的第20回合的回合结束时自己决斗胜利。'),
(35756798, 'Final Cross', '最终交错', 'ファイナル・クロス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：同调怪兽被送去自己墓地的自己回合，以自己场上1只同调怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。以原本卡名包含「战士」、「同调士」、「星尘」之内任意种的同调怪兽为对象把这张卡发动的场合，可以再选自己墓地1只同调怪兽让作为对象的怪兽的攻击力上升那个攻击力数值。'),
(18591904, 'Final Destiny', '最终战争', '最終戦争', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃5张手卡。场上的卡全部破坏。'),
(300201003, 'Final Draw', NULL, NULL, 'Skill Card', 'Yugi', NULL, NULL, NULL, NULL, NULL),
(73134082, 'Final Flame', '火刑', '火あぶりの刑', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(89719143, 'Final Fusion', '决战融合', '決戦融合－ファイナル・フュージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的融合怪兽和对方场上的融合怪兽进行战斗的战斗步骤，以那2只融合怪兽为对象才能发动。那次攻击无效，双方玩家受到那2只融合怪兽的攻击力合计数值的伤害。'),
(16832845, 'Final Geas', '最终禁忌', 'ファイナル・ギアス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：原本等级是7星以上的怪兽从自己以及对方的场上各有1只以上被送去墓地的回合才能发动。双方墓地的怪兽全部除外。那之后，可以把这个效果除外的怪兽之内等级最高的1只魔法师族怪兽在自己场上特殊召唤。'),
(23269426, 'Final Gesture', '最后的同调', '最期の同調', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只3星怪兽为对象才能发动。那1只同名怪兽从自己的手卡·墓地特殊召唤。这个效果特殊召唤的怪兽的效果无效化。作为对象的怪兽在这个回合的结束阶段破坏。'),
(51549976, 'Final Inzektion', '最终甲虫注射', 'ファイナル・インゼクション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的5张名字带有「甲虫装机」的卡送去墓地才能发动。对方场上的卡全部破坏。对方在这个回合的战斗阶段中不能把手卡·墓地发动的效果怪兽的效果发动。'),
(17956906, 'Final Light', '终幕之光', '終幕の光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付1000的倍数的基本分，以支付的基本分每1000为1只的自己墓地的「女武神」怪兽为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。那之后，对方可以从自身墓地选最多有这个效果特殊召唤的怪兽数量的攻击力2000以下的怪兽特殊召唤。'),
(87622767, 'Final Psychic Ogre', '最终念力食人魔', 'ファイナルサイコオーガ', 'Effect Monster', 'Psychic', 'EARTH', 5, 2200, 1700, '这张卡战斗破坏对方怪兽的场合，可以支付800基本分选择自己墓地存在的1只念动力族怪兽加入手卡。'),
(60369732, 'Final Ritual of the Ancients', '大邪神的仪式', '大邪神の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「大邪神 雷瑟夫」降临必要。必须把场上·手卡合计8星以上的卡作为祭品。');